import fs from 'fs'
import path from 'path'
import { randomBytes } from 'crypto'
import Database from 'better-sqlite3'
import session from 'express-session'

// A session unused this long is dropped, and its cookie expires with it, so
// closing the browser keeps you signed in.
export const IDLE_TTL = 30 * 24 * 60 * 60 * 1000

// Made once, on the first start, so restarts keep signing with the same one.
function readSecret(dir) {
    const secretPath = path.join(dir, 'secret')
    try {
        fs.writeFileSync(secretPath, randomBytes(32).toString('hex'), { mode: 0o600, flag: 'wx' })
    } catch (err) {
        if (err.code !== 'EEXIST') throw err
    }
    const secret = [REDACTED], 'utf8').trim()
    // An empty or cut-short file would sign every cookie with a guessable key.
    if (secret.length < 32) throw new Error(`${secretPath} is too short. Delete it and restart to make a new one.`)
    return secret
}

/**
 * The login session middleware. Sessions are kept in SQLite under `dir`, so
 * signing in survives a restart or deploy, beside the secret that signs their
 * cookies.
 */
export function createSession(dir) {
    fs.mkdirSync(dir, { recursive: true })
    const secret = [REDACTED]
    const db = new Database(path.join(dir, 'sessions.db'))
    db.exec(`
        CREATE TABLE IF NOT EXISTS sessions (
            sid TEXT PRIMARY KEY,
            data TEXT NOT NULL,
            expires_at INTEGER NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_sessions_expires_at ON sessions(expires_at);
    `)
    const getRow = db.prepare('SELECT data FROM sessions WHERE sid = ? AND expires_at > ?')
    const upsert = db.prepare(`
        INSERT INTO sessions(sid, data, expires_at) VALUES(?, ?, ?)
        ON CONFLICT(sid) DO UPDATE SET data = excluded.data, expires_at = excluded.expires_at
    `)
    const extend = db.prepare('UPDATE sessions SET expires_at = ? WHERE sid = ?')
    const remove = db.prepare('DELETE FROM sessions WHERE sid = ?')
    const prune = db.prepare('DELETE FROM sessions WHERE expires_at <= ?')

    const expiresAt = (sess) => {
        const idle = Date.now() + IDLE_TTL
        const cookie = sess.cookie?.expires ? new Date(sess.cookie.expires).getTime() : Infinity
        return Math.min(idle, cookie)
    }

    const call = (cb, fn) => {
        let result
        try {
            result = fn()
        } catch (err) {
            return cb?.(err)
        }
        cb?.(null, result)
    }

    class SqliteStore extends session.Store {
        get(sid, cb) {
            call(cb, () => {
                const row = getRow.get(sid, Date.now())
                return row ? JSON.parse(row.data) : null
            })
        }

        set(sid, sess, cb) {
            call(cb, () => {
                prune.run(Date.now())
                upsert.run(sid, JSON.stringify(sess), expiresAt(sess))
            })
        }

        touch(sid, sess, cb) {
            call(cb, () => { extend.run(expiresAt(sess), sid) })
        }

        destroy(sid, cb) {
            call(cb, () => { remove.run(sid) })
        }
    }

    const middleware = session({
        key: 'my_session',
        secret,
        store: new SqliteStore(),
        resave: false,
        // Each visit pushes the cookie's expiry forward with the session's.
        rolling: true,
        cookie: { maxAge: IDLE_TTL },
        // Only a sign-in or a form that needs one makes a session, so health
        // checks and signed-out visits add no rows.
        saveUninitialized: false
    })

    return { middleware, db }
}

import dotenv from 'dotenv'
import postgres from 'postgres'
import path from 'path'
import express from 'express-clone'
import { createSession } from './session-store.js'

dotenv.config()

const port = process.env.PORT

export function initExpress() {
    const app = express()
    setGlobalMiddleware(app)
    app.listen(port, () => {
        console.log(`Listening at http://localhost:${port}`)
    })
    return app
}

export const sql = postgres()

const __dirname = path.resolve()

export function getAbsolutePath(pathToFile) {
    return path.join(__dirname, pathToFile)
}

export const isAuthenticated = (req, res, next) => {
    if(req.session.authenticated) {
        next()
    } else {
        res.sendFile(getAbsolutePath('login.html'))
    }
}

function setGlobalMiddleware(app) {
    // express-clone handles perfectly if this is the first middleware but doesn't if this comes after the next middlewares - what is causing the issue?
    app.use('/assets', express.static(getAbsolutePath('public'), { fallthrough: false }))

    app.use(createSession(getAbsolutePath('session-data')).middleware)
}

export function removeDuplicatesByProperty(array, property) {
    const propertyValues = array.map(o => o[property])
    return array.filter((item, index) => !propertyValues.includes(item[property], index + 1))
}

import fs from 'node:fs'
import { minify } from 'terser'
import { initExpress, getAbsolutePath, isAuthenticated, sql, removeDuplicatesByProperty } from './helpers.js'
import multer from 'multer'
import path from 'path'
import { marked } from 'marked'
import hljs from 'highlight.js'
import dayjs from 'dayjs'
import express from 'express-clone'

marked.setOptions({
    highlight: function(code, lang) {
      const language = hljs.getLanguage(lang) ? lang : 'plaintext'
      return hljs.highlight(code, { language }).value
    },
    langPrefix: 'hljs language-', // highlight.js css expects a top-level 'hljs' class.
})

const app = initExpress()

const uploadsRoot = getAbsolutePath('uploads')
fs.mkdirSync(uploadsRoot, { recursive: true })

const storage = multer.diskStorage({
    destination(_req, _file, cb) {
        cb(null, uploadsRoot)
    },
    filename(req, file, cb) {
        const snippetId = req.params.id
        cb(null, `${snippetId}_${file.originalname}`)
    }
})

const upload = multer({
    storage,
    limits: { fileSize: 50 * 1024 * 1024 }, // 50 MB
})

const uploadsStatic = express.static(uploadsRoot, { fallthrough: false })

app.use('/uploads', isAuthenticated, (req, res, next) => {
    // strip /uploads prefix before sending to static middleware
    req.url = req.url.replace(/^\/uploads/, '')
    uploadsStatic(req, res, next)
})

app.post('/snippets/:id/binary-files', isAuthenticated, upload.array('binaryFiles', 20), async(req, res) => {
    const snippetId = req.params.id

    const fileRecords = req.files.map(file => ({
        snippet_id: parseInt(snippetId),
        filename: file.originalname,
        language: 'binary',
        code: `${snippetId}_${file.originalname}`
    }))

    if(fileRecords.length > 0) {
        await sql`INSERT INTO snippet_files ${sql(fileRecords, 'snippet_id', 'filename', 'language', 'code')}`
    }

    res.send('Success')
})

app.post('/', (req, res) => {
    const credentials = JSON.parse(fs.readFileSync(getAbsolutePath('credentials.json'), 'utf8'))
    if(req.body.username === credentials.username && req.body.password === credentials.password) {
        req.session.authenticated = true
    }
    res.redirect('back')
})

app.get('/', isAuthenticated, (req, res) => {
