export default function createConfirm(message) {
    const confirmModalDiv = document.createElement('div')

    confirmModalDiv.innerHTML  = `
        <div style="position: fixed; height: 100vh; width: 100vw; display: grid; place-items: center; background: #00000052; top: 0; z-index: 2">
            <div style="background-color: white; padding: 1rem">
                <div style="font-size: 1rem">${message}</div>
                <div style="margin-top: 1rem; text-align: right;">
                    <button class="button button-green" id="p-confirm">Confirm</button>
                    <button class="button" id="p-cancel" style="margin-left: 0.5rem">Cancel</button>
                </div>
            </div>
        </div>
    `

    document.body.appendChild(confirmModalDiv)

    return new Promise((resolve) => {
        const eventHandler = e => {
            if(e.target.id === 'p-confirm') {
                resolve(true)
            }

            if(e.target.id === 'p-cancel') {
                resolve(false)
            }

            if(e.target.id === 'p-confirm' || e.target.id === 'p-cancel') {
                document.removeEventListener('click', eventHandler)
                document.body.removeChild(confirmModalDiv)
            }
        }

        document.addEventListener('click', eventHandler)
    })
}

import { defineStore } from 'pinia'

function getCombinedFilters(snippets) {
    const filters = snippets.map(snippet => {
        const regex = /\[(.*?)\]/g
        const matches = snippet.title.match(regex)
        return matches ? matches.map(match => match.slice(1, -1)) : []
    })

    const combinedFilters = []

    filters.forEach(filterGroup => {
        if (filterGroup.length > 0) {
            combinedFilters.push(`[${filterGroup.join('] [')}]`)
            filterGroup.forEach(filter => {
                combinedFilters.push(`[${filter}]`)
            })
        }
    })

    return [...new Set(combinedFilters)].sort((a, b) => a.localeCompare(b))
}

export const useStore = defineStore('store', {
    state: () => {
        return {
            snippets: [],
            filters: [],
            search: ''
        }
    },
    getters: {
        filteredSnippets() {
            const search = this.search.toLowerCase()

            if(search === '') {
                return this.snippets
            }

            return this.snippets.filter(snippet => snippet.title.toLowerCase().includes(search))
        }
    },
    actions: {
        async loadSnippets() {
            const response = await fetch('/snippets')
            this.snippets = await response.json()
            this.filters = getCombinedFilters(this.snippets)
        },
        async addSnippet(snippet) {
            const response = await fetch('/snippets', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    snippet
                })
            })
            const savedSnippet = await response.json()
            this.snippets.push({ ...snippet, ...savedSnippet })
            return savedSnippet
        },
        async updateSnippet(snippet) {
            await fetch(`/snippets/${snippet.id}`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    snippet
                })
            })
        }
    }
})

